{"version":"2b1","blocks":[{"type":"text","text":"Adult tickets cost $8 each; child tickets cost $5 each. The selected ticket type applies to the whole order."},{"type":"ui","source":"{
  "root": "layout",
  "elements": {
    "layout": {"type": "Stack", "props": {}, "children": ["input", "ticketType", "result"]},
    "input": {"type": "Control", "props": {"label": "Ticket count", "min": 1, "max": 5, "choices": [], "value": {"$bindState": "/count"}}},
    "ticketType": {"type": "Control", "props": {"label": "Ticket type", "min": 0, "max": 1, "choices": ["Adult", "Child"], "value": {"$bindState": "/child"}}},
    "result": {
      "type": "Metric",
      "props": {
        "label": "Total ($)",
        "value": {
          "$computed": "Multiply",
          "args": {
            "a": {"$state": "/count"},
            "b": {
              "$computed": "Excess",
              "args": {"a": 8, "b": {"$computed": "Multiply", "args": {"a": 3, "b": {"$state": "/child"}}}}
            }
          }
        }
      }
    }
  }
}","state":[{"name":"count","value":3},{"name":"child","value":0}]}]}
